mapper.select:
SELECT EXISTS (
    SELECT 1
      FROM users
     WHERE email = #{email}
       AND email_verified = TRUE
)

mapper.insert:
INSERT INTO users (
       email
     , password_hash
     , nickname
     , birth_date
     , phone
     , gender
     , address
     , agreed_terms
     , agreed_privacy
     , role
     , status
     , email_verified
     , created_at
) VALUES (
       #{email}
     , #{passwordHash}
     , #{nickname}
     , #{birthDate}
     , #{phone}
     , #{gender}
     , #{address}
     , #{agreedTerms}
     , #{agreedPrivacy}
     , #{role}
     , #{status}
     , #{emailVerified}
     , #{createdAt}
)

mapper.update:
UPDATE users
   SET password_hash   = #{passwordHash}
     , nickname        = #{nickname}
     , birth_date      = #{birthDate}
     , phone           = #{phone}
     , gender          = #{gender}
     , address         = #{address}
     , agreed_terms    = #{agreedTerms}
     , agreed_privacy  = #{agreedPrivacy}
     , status          = #{status}
     , updated_at      = CURRENT_TIMESTAMP
 WHERE user_id = #{userId}
   AND email_verified = FALSE

