UPDATE user_tokens
   SET used_at = CURRENT_TIMESTAMP
 WHERE user_id = #{userId}
   AND purpose = #{purpose}
   AND used_at IS NULL

UPDATE users
   SET role = #{role}
     , updated_at = CURRENT_TIMESTAMP
 WHERE user_id = #{userId}
